    if not data:
        return

    it = iter(data)
    L = int(next(it))
    C = int(next(it))

    grid = []
    eq_counts = []
    eq_target = []
    var_to_eqs = defaultdict(list)

    for _ in range(L):
        row = []
        counts = {}
        for _ in range(C):
            v = next(it)
            row.append(v)
            counts[v] = counts.get(v, 0) + 1
        S = int(next(it))
        grid.append(row)

        eq_id = len(eq_counts)
        eq_counts.append(counts)
        eq_target.append(S)
        for v in counts:
            var_to_eqs[v].append(eq_id)

    col_sums = [int(next(it)) for _ in range(C)]

    for j in range(C):
        counts = {}
        for i in range(L):
            v = grid[i][j]
            counts[v] = counts.get(v, 0) + 1

        eq_id = len(eq_counts)
        eq_counts.append(counts)
        eq_target.append(col_sums[j])
        for v in counts:
            var_to_eqs[v].append(eq_id)

    known = {}
    q = deque()

    for eq_id, counts in enumerate(eq_counts):
        if len(counts) == 1:
            q.append(eq_id)

    while q:
        eq_id = q.popleft()
        target = eq_target[eq_id]
        counts = eq_counts[eq_id]

        unknown = None
        sum_known = 0
        multiple = False

        for v, coeff in counts.items():
            if v in known:
                sum_known += coeff * known[v]
            else:
                if unknown is None:
                    unknown = v
                else:
                    multiple = True
                    break

        if multiple or unknown is None:
            continue

        coeff = counts[unknown]
        val = (target - sum_known) // coeff
        known[unknown] = val

        for neq in var_to_eqs[unknown]:
            q.append(neq)

    all_vars = set()
    for row in grid:
        all_vars.update(row)

    out = []
    for v in sorted(all_vars):
        out.append(f"{v} {known[v]}")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
